sys_script.script:
(function executeRule(current, previous /*null when async*/) {

    // Only validate active Care Plans
    if (current.active != true) {
        return;
    }

    // Only validate Active status
    if (current.care_plan_status != 'Active') {
        return;
    }

    // Required fields for duplicate check
    if (current.patient.nil() ||
        current.admission.nil() ||
        current.care_plan_type.nil()) {
        return;
    }

    var duplicate = new GlideRecord('x_2130921_caresy_0_care_plan');

    duplicate.addQuery('patient', current.patient);
    duplicate.addQuery('admission', current.admission);
    duplicate.addQuery('care_plan_type', current.care_plan_type);
    duplicate.addQuery('care_plan_status', 'Active');
    duplicate.addQuery('active', true);

    // When updating an existing Care Plan,
    // don't compare the record with itself.
    if (!current.isNewRecord()) {
        duplicate.addQuery('sys_id', '!=', current.sys_id);
    }

    duplicate.setLimit(1);
    duplicate.query();

    if (duplicate.next()) {

        gs.addErrorMessage(
            'An active Care Plan of the same type already exists for this Patient and Admission.'
        );

        current.setAbortAction(true);
    }

})(current, previous);
